export {
  init,
  Message,
  Model,
  OutMessage,
  reflectChecked,
  setChecked,
  SetChecked,
  ToggledChecked,
  update,
  view,
} from "../checkbox";
export type {
  CheckboxAttributes,
  Commands,
  InitConfig,
  InitReturn,
  Toggled,
  UpdateReturn,
  ViewInputs,
} from "../checkbox";

export {
  shadcnCheckboxControlClassName,
  shadcnCheckboxDescriptionClassName,
  shadcnCheckboxLabelClassName,
  shadcnCheckboxRowClassName,
  shadcnCheckboxTextClassName,
} from "./view";

export {
  checkboxControlClassName as shadcnCheckboxControlClassName,
  checkboxDescriptionClassName as shadcnCheckboxDescriptionClassName,
  checkboxLabelClassName as shadcnCheckboxLabelClassName,
  checkboxRowClassName as shadcnCheckboxRowClassName,
  checkboxTextClassName as shadcnCheckboxTextClassName,
} from "../checkbox/view";

import { describe, expect, test } from "vitest";

import * as Checkbox from "./index";

describe("shadcn Checkbox registry view", () => {
  test("reuses the Foldkit Checkbox functional contract", () => {
    expect(Checkbox.init).toBeTypeOf("function");
    expect(Checkbox.update).toBeTypeOf("function");
    expect(Checkbox.view).toBeTypeOf("function");
    expect(Checkbox.shadcnCheckboxControlClassName).toContain("rounded");
  });
});
